import { Controller, HttpCode, Patch, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const STATUSES = ['신청', '승인', '반려', '마감', '마감 취소', '승인 취소'];

// 가정: 발령상태 전환표. BEHAVIOR.md에는 신청→승인·반려만 있고,
// 승인 이후 단계는 공통 P8(승인 취소·마감 취소 절차)에 따라 정한 값이다.
const NEXT_STATUS: Record<string, string[]> = {
  '신청': ['승인'],
  '승인': ['마감', '승인 취소'],
  '마감': ['마감 취소'],
};

function isId(value: unknown): boolean {
  return (typeof value === 'number' || typeof value === 'string') && /^[0-9]+$/.test(String(value));
}

function invalidInput(message: string): ApiError {
  return new ApiError(422, 'INVALID_APPOINTMENT_INPUT', message);
}

@Controller('api/v1')
export class FnSfr01302Controller {
  @Post('/personnel-appointments')
  @HttpCode(200)
  async createPersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    if (!isId(data['employeeId'])) {
      throw invalidInput('대상 임직원을 선택해 주세요.');
    }
    const appointmentType = typeof data['appointmentType'] === 'string' ? data['appointmentType'].trim() : '';
    if (appointmentType === '' || appointmentType.length > 50) {
      throw invalidInput('발령 구분을 50자 이내로 입력해 주세요.');
    }
    const appointmentDate = data['appointmentDate'];
    if (typeof appointmentDate !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(appointmentDate)) {
      throw invalidInput('발령일자를 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (!isId(data['departmentId'])) {
      throw invalidInput('발령 후 부서를 선택해 주세요.');
    }
    const rawPosition = data['positionAfter'];
    if (rawPosition !== undefined && rawPosition !== null && typeof rawPosition !== 'string') {
      throw invalidInput('발령 후 직위·직책 형식이 올바르지 않습니다.');
    }
    const positionAfter = typeof rawPosition === 'string' && rawPosition.trim() !== '' ? rawPosition.trim() : null;
    if (positionAfter !== null && positionAfter.length > 100) {
      throw invalidInput('발령 후 직위·직책은 100자 이내로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const records = await db.query(
        'SELECT personnel_record_id FROM personnel_record WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId: String(data['employeeId']) },
      );
      if (records.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '인사기록카드에 등록되지 않은 임직원입니다.');
      }
      const departments = await db.query(
        'SELECT department_id FROM department WHERE department_id = CAST(:departmentId AS bigint)',
        { departmentId: String(data['departmentId']) },
      );
      if (departments.length === 0) {
        throw invalidInput('발령 후 부서를 찾을 수 없습니다.');
      }
      const rows = await db.query(
        `INSERT INTO personnel_appointment
           (employee_id, department_id, appointment_type, appointment_date, position_after, status, created_at, updated_at)
         VALUES
           (CAST(:employeeId AS bigint), CAST(:departmentId AS bigint), :appointmentType,
            CAST(:appointmentDate AS date), :positionAfter, '신청', now(), now())
         RETURNING personnel_appointment_id AS "personnelAppointmentId", status`,
        {
          employeeId: String(data['employeeId']),
          departmentId: String(data['departmentId']),
          appointmentType,
          appointmentDate,
          positionAfter,
        },
      );
      return rows[0];
    });
  }

  @Patch('/personnel-appointments/:personnelAppointmentId/status')
  async updatePersonnelAppointmentStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = req.params['personnelAppointmentId'];
    if (!isId(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '인사발령 ID 형식이 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const status = data['status'];
    if (typeof status !== 'string' || !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '발령 상태 값이 올바르지 않습니다.');
    }
    if (status === '반려') {
      // 가정: 반려는 반려 사유가 필수인데 이 API에는 사유 입력이 없어 처리하지 않는다.
      throw new ApiError(400, 'VALIDATION_FAILED', '반려는 반려 사유가 필요해 이 화면에서 처리할 수 없습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT status FROM personnel_appointment
         WHERE personnel_appointment_id = CAST(:id AS bigint)
         FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '발령 대상자를 찾을 수 없습니다.');
      }
      const current = String(found[0]['status']);
      const allowed = NEXT_STATUS[current] ?? [];
      if (!allowed.includes(status)) {
        throw new ApiError(409, 'APPOINTMENT_ALREADY_PROCESSED', '이미 처리된 발령 대상자입니다. 정해진 절차(승인 취소·마감 취소)를 이용해 주세요.');
      }
      const rows = await db.query(
        `UPDATE personnel_appointment
         SET status = :status,
             processed_by = CAST(:userId AS bigint),
             processed_at = now(),
             updated_at = now()
         WHERE personnel_appointment_id = CAST(:id AS bigint)
         RETURNING personnel_appointment_id AS "personnelAppointmentId", status`,
        { status, userId: user.id, id },
      );
      await db.execute(
        `INSERT INTO change_history
           (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at)
         VALUES
           (CAST(:userId AS bigint), 'personnel_appointment', CAST(:id AS bigint), '발령상태 변경', now(), :content, now(), now())`,
        { userId: user.id, id, content: '발령상태: ' + current + ' → ' + status },
      );
      return rows[0];
    });
  }
}

