import { useState } from 'react';
import { Badge, Band, DataTable, DateInput, DateText, Drawer, Field, Form, LookupSelect, Pairs, RefName, Select, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

// 가정: 발령상태 전환표 (서버와 같다)
const NEXT_STATUS: Record<string, string[]> = {
  '신청': ['승인'],
  '승인': ['마감', '승인 취소'],
  '마감': ['마감 취소'],
};

export default function FnSfr01302Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 결과를 목록으로 보인다
  const [rows, setRows] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [target, setTarget] = useState<Row | null>(null);
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [appointmentType, setAppointmentType] = useState('');
  const [appointmentDate, setAppointmentDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [positionAfter, setPositionAfter] = useState('');
  const [nextStatus, setNextStatus] = useState('');

  function openCreate() {
    setEmployeeId('');
    setAppointmentType('');
    setAppointmentDate('');
    setDepartmentId('');
    setPositionAfter('');
    setCreating(true);
  }

  function openStatus(row: Row) {
    setNextStatus('');
    setTarget(row);
  }

  async function submitCreate() {
    if (employeeId === '') throw new Error('대상 임직원을 선택해 주세요.');
    if (appointmentType.trim() === '') throw new Error('발령 구분을 입력해 주세요.');
    if (appointmentDate === '') throw new Error('발령일자를 입력해 주세요.');
    if (departmentId === '') throw new Error('발령 후 부서를 선택해 주세요.');
    const body: Row = { employeeId, appointmentType: appointmentType.trim(), appointmentDate, departmentId };
    if (positionAfter.trim() !== '') body.positionAfter = positionAfter.trim();
    const res = await call('POST', '/personnel-appointments', role, body);
    setRows([{ ...body, personnelAppointmentId: res.personnelAppointmentId, status: res.status }, ...rows]);
    setCreating(false);
    notify('발령 대상자를 등록했습니다.');
  }

  async function submitStatus() {
    if (target === null) return;
    if (nextStatus === '') throw new Error('변경할 발령 상태를 선택해 주세요.');
    const res = await call('PATCH', '/personnel-appointments/' + String(target.personnelAppointmentId) + '/status', role, { status: nextStatus });
    setRows(rows.map((r) => (r.personnelAppointmentId === target.personnelAppointmentId ? { ...r, status: res.status } : r)));
    setTarget(null);
    notify('발령상태를 변경했습니다.');
  }

  const nextOptions: [string, string][] = target === null ? [] : (NEXT_STATUS[String(target.status)] ?? []).map((s): [string, string] => [s, s]);

  return (
    <div>
      <h1>인사발령 대상자</h1>
      <Band total={rows.length}>
        <button onClick={openCreate}>발령 대상자 등록</button>
      </Band>
      <DataTable
        rows={rows}
        empty='아직 등록한 발령 대상자가 없습니다. 발령 대상자 등록 버튼으로 첫 대상자를 등록해 주세요.'
        columns={[
          { key: 'employeeId', label: '발령 대상 임직원', render: (r) => <RefName table='employee' role={role} value={r.employeeId} /> },
          { key: 'appointmentType', label: '발령 구분' },
          { key: 'appointmentDate', label: '발령일자', render: (r) => <DateText value={r.appointmentDate} /> },
          { key: 'status', label: '발령 상태', render: (r) => <Badge value={r.status} /> },
          {
            key: 'action',
            label: '처리',
            render: (r) =>
              (NEXT_STATUS[String(r.status)] ?? []).length > 0 ? (
                <button className={'ghost'} onClick={() => openStatus(r)}>상태 변경</button>
              ) : null,
          },
        ]}
      />
      {creating && (
        <Drawer title='발령 대상자 등록' onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit='등록'>
            <Field label='발령 대상 임직원' required>
              <LookupSelect table='employee' role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
            <Field label='발령 구분' required>
              <TextInput value={appointmentType} onChange={setAppointmentType} />
            </Field>
            <Field label='발령일자' required>
              <DateInput value={appointmentDate} onChange={setAppointmentDate} />
            </Field>
            <Field label='발령 후 부서' required>
              <LookupSelect table='department' role={role} value={departmentId} onChange={setDepartmentId} />
            </Field>
            <Field label='발령 후 직위·직책'>
              <TextInput value={positionAfter} onChange={setPositionAfter} />
            </Field>
          </Form>
        </Drawer>
      )}
      {target !== null && (
        <Drawer title='발령상태 변경' onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['발령 대상 임직원', <RefName table='employee' role={role} value={target.employeeId} />],
              ['발령 구분', String(target.appointmentType ?? '')],
              ['현재 발령 상태', <Badge value={target.status} />],
            ]}
          />
          <Form
            onSubmit={submitStatus}
            submit='변경'
            note='변경 내용과 처리자·처리 일시가 이력으로 남습니다. 마감된 대상자는 마감 취소 절차로만 되돌릴 수 있습니다.'
          >
            <Field label='변경할 발령 상태' required>
              <Select value={nextStatus} onChange={setNextStatus} options={nextOptions} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
